window.closeMiniPlayer = function(e) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }
  const videoElement = document.getElementById('luminaVideo');
  const iframeElement = document.getElementById('luminaIframe');
  const playerModal = document.getElementById('playerModal');
  const miniPlayer = document.getElementById('miniPlayer');
  
  clearTimeout(streamWatchdogTimeout);

  if (playerModal) {
    playerModal.classList.remove('is-embedded-player');
  }

  window.currentEmbeddedYouTubeId = null;

  if (iframeElement) {
    iframeElement.src = 'about:blank';
    iframeElement.style.display = 'none';
  }

  if (videoElement) {
    videoElement.pause();
    videoElement.removeAttribute('src');
    videoElement.load();
    videoElement.style.display = 'block';
  }
  
  if (hlsInstance) {
    try {
      hlsInstance.destroy();
    } catch (e) {}
    hlsInstance = null;
  }

  // Restore phone screen hardware brightness back to system default
  try {
    if (window.AndroidMedia) {
      if (window.AndroidMedia.resetBrightness) window.AndroidMedia.resetBrightness();
      else if (window.AndroidMedia.setBrightness) window.AndroidMedia.setBrightness(-1);
    }
  } catch (eB) {}
  
  const brightOverlay = document.getElementById('playerBrightnessOverlay');
  if (brightOverlay) brightOverlay.style.opacity = '0';
  // Stop native DDP hardware audio decoder
  if (window.AndroidMedia && window.AndroidMedia.stopNativeAudio) {
    window.AndroidMedia.stopNativeAudio();
  }
  isNativeDDPActive = false;

  // Stop torrent engine if streaming
  if (typeof torrentHudInterval !== 'undefined' && torrentHudInterval) {
    clearInterval(torrentHudInterval);
    torrentHudInterval = null;
  }
  const torrentHud = document.getElementById('torrentHud');
  if (torrentHud) torrentHud.style.display = 'none';
  if (window.AndroidMedia && window.AndroidMedia.stopTorrentStream) {
    try { window.AndroidMedia.stopTorrentStream(); } catch(eT) {}
  }

  if (playerModal) {
    playerModal.classList.remove('active');
    playerModal.style.display = 'none';
  }
  
  if (miniPlayer) {
    miniPlayer.classList.remove('active');
  }

  // Restore orientation and screen state (Task 5)
  try {
    if (window.AndroidMedia) {
      if (window.AndroidMedia.setOrientation) window.AndroidMedia.setOrientation('portrait');
      if (window.AndroidMedia.resetOrientationToDefault) window.AndroidMedia.resetOrientationToDefault();
      if (window.AndroidMedia.keepScreenOn) window.AndroidMedia.keepScreenOn(false);
      if (window.AndroidMedia.setFullscreen) window.AndroidMedia.setFullscreen(false);
    }
  } catch (e2) {}
  
  // Hide audio artwork
  const artwork = document.getElementById('playerAudioArtwork');
  if (artwork) artwork.style.display = 'none';
  
  isPlaying = false;
  currentPlayingChannel = null;
  updatePlayPauseIcons(false);
  showToast('Playback Closed');
};

window.closeMiniPlayerCompletely = function(e) {
  closeMiniPlayer(e);
};

// Fullscreen & Mini-Player Channel Navigation (⏮ Backward / ⏭ Forward)
window.playPreviousChannel = function(e) {
  if (e) {
    try { e.preventDefault(); e.stopPropagation(); } catch (err) {}
  }
  if (!currentPlayingChannel) return;

  let activeList = channelsData;
  if (currentPlayingChannel.isLocal && Array.isArray(customLocalMedia) && customLocalMedia.length > 0) {
    activeList = customLocalMedia;
  } else if (currentPlayingChannel.type === 'radio') {
    activeList = channelsData.filter(c => c.type === 'radio');
  } else if (currentPlayingChannel.type === 'tv') {
    activeList = channelsData.filter(c => c.type === 'tv');
  }

  if (!Array.isArray(activeList) || activeList.length === 0) activeList = channelsData;
  if (activeList.length === 0) return;

  // Filter out quarantined channels from sequential navigation
  if (typeof getChannelHealthStatus === 'function') {
    activeList = activeList.filter(c => getChannelHealthStatus(c.id) !== 'quarantined');
  }
  if (activeList.length === 0) return;

  const currentIdx = activeList.findIndex(c => c.id === currentPlayingChannel.id);
  const prevIdx = currentIdx > 0 ? currentIdx - 1 : activeList.length - 1;
  const prevChannel = activeList[prevIdx];

  if (prevChannel) {
    playChannel(prevChannel);
    const badge = prevChannel.flag || (prevChannel.type === 'radio' ? '📻' : '📺');
    showToast('⏮ ' + badge + ' ' + (prevChannel.name || 'Previous Channel'));
  }
};

window.playNextChannel = function(e) {
  if (e) {
    try { e.preventDefault(); e.stopPropagation(); } catch (err) {}
  }
  if (!currentPlayingChannel) return;

  let activeList = channelsData;
  if (currentPlayingChannel.isLocal && Array.isArray(customLocalMedia) && customLocalMedia.length > 0) {
    activeList = customLocalMedia;
  } else if (currentPlayingChannel.type === 'radio') {
    activeList = channelsData.filter(c => c.type === 'radio');
  } else if (currentPlayingChannel.type === 'tv') {
    activeList = channelsData.filter(c => c.type === 'tv');
  }

  if (!Array.isArray(activeList) || activeList.length === 0) activeList = channelsData;
  if (activeList.length === 0) return;

  // Filter out quarantined channels from sequential navigation
  if (typeof getChannelHealthStatus === 'function') {
    activeList = activeList.filter(c => getChannelHealthStatus(c.id) !== 'quarantined');
  }
  if (activeList.length === 0) return;

  const currentIdx = activeList.findIndex(c => c.id === currentPlayingChannel.id);
  const nextIdx = currentIdx >= 0 && currentIdx < activeList.length - 1 ? currentIdx + 1 : 0;
  const nextChannel = activeList[nextIdx];

  if (nextChannel) {
    playChannel(nextChannel);
    const badge = nextChannel.flag || (nextChannel.type === 'radio' ? '📻' : '📺');
    showToast('⏭ ' + badge + ' ' + (nextChannel.name || 'Next Channel'));
  }
};

// ==========================================================
// MINI-PLAYER SWIPE-DOWN GESTURE (Swipe Down to Cut Media)
// ==========================================================
function initMiniPlayerSwipe() {
  const miniPlayer = document.getElementById('miniPlayer');
  if (!miniPlayer) return;

  let startY = 0;
  let currentDeltaY = 0;
  let isSwiping = false;

  miniPlayer.addEventListener('touchstart', (e) => {
    if (e.target.closest('button')) return;
    if (e.touches && e.touches.length === 1) {
      startY = e.touches[0].clientY;
      currentDeltaY = 0;
      isSwiping = true;
      miniPlayer.classList.add('swiping-down');
    }
  }, { passive: true });

  miniPlayer.addEventListener('touchmove', (e) => {
    if (!isSwiping || !e.touches || e.touches.length === 0) return;
    const clientY = e.touches[0].clientY;
    const dy = clientY - startY;
    if (dy > 0) {
      currentDeltaY = dy;
      const opacity = Math.max(0, 1 - (dy / 140));
      miniPlayer.style.transform = `translateY(${dy}px)`;
      miniPlayer.style.opacity = opacity;
    } else {
      currentDeltaY = 0;
      miniPlayer.style.transform = 'translateY(0)';
      miniPlayer.style.opacity = '1';
    }
  }, { passive: true });

  miniPlayer.addEventListener('touchend', () => {
    if (!isSwiping) return;
    isSwiping = false;
    miniPlayer.classList.remove('swiping-down');

    // If swiped down > 40px, dismiss and cut running media immediately
    if (currentDeltaY > 40) {
      miniPlayer.classList.add('dismissing');
      setTimeout(() => {
        closeMiniPlayer();
        miniPlayer.style.transform = '';
        miniPlayer.style.opacity = '';
        miniPlayer.classList.remove('dismissing');
      }, 180);
    } else {
      // Snap back smoothly
      miniPlayer.style.transform = 'translateY(0)';
      miniPlayer.style.opacity = '1';
      setTimeout(() => {
        miniPlayer.style.transform = '';
        miniPlayer.style.opacity = '';
      }, 200);
    }
  }, { passive: true });

  miniPlayer.addEventListener('touchcancel', () => {
    isSwiping = false;
    miniPlayer.classList.remove('swiping-down');
    miniPlayer.style.transform = '';
    miniPlayer.style.opacity = '';
  }, { passive: true });
}

window.togglePlay = function() {
  const videoElement = document.getElementById('luminaVideo');
  if (!videoElement) return;
  if (videoElement.paused) {
    videoElement.play().catch(() => {});
    isPlaying = true;
  } else {
    videoElement.pause();
    isPlaying = false;
  }
  updatePlayPauseIcons(isPlaying);
};

function updatePlayPauseIcons(playing) {
  const playerBox = document.getElementById('playerPlaySvgBox');
  const miniBox = document.getElementById('miniPlaySvgBox');
  const pauseSvg = '<svg viewBox="0 0 24 24" width="30" height="30" fill="#FFFFFF"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>';
  const playSvg = '<svg viewBox="0 0 24 24" width="30" height="30" fill="#FFFFFF" style="margin-left: 3px;"><path d="M8 5v14l11-7z"/></svg>';
  const miniPause = '<svg viewBox="0 0 24 24" width="20" height="20" fill="#FFFFFF"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>';
  const miniPlay = '<svg viewBox="0 0 24 24" width="20" height="20" fill="#FFFFFF" style="margin-left: 2px;"><path d="M8 5v14l11-7z"/></svg>';
  
  if (playerBox) playerBox.innerHTML = playing ? pauseSvg : playSvg;
  if (miniBox) miniBox.innerHTML = playing ? miniPause : miniPlay;

  const waveBars = document.querySelectorAll('.mini-live-wave .wave-bar');
  waveBars.forEach(b => {
    b.style.animationPlayState = playing ? 'running' : 'paused';
    if (!playing) b.style.height = '4px';
  });
}

function showSeekRipple(seconds) {
  const playerModal = document.getElementById('playerModal');
  if (!playerModal) return;
  const isFwd = seconds > 0;
  const ripple = document.createElement('div');
  ripple.className = 'seek-ripple-feedback ' + (isFwd ? 'right' : 'left');
  ripple.innerHTML = `
    <div class="seek-ripple-circle"></div>
    <span class="seek-ripple-text">${isFwd ? '⏩ +' + Math.abs(seconds) + 's' : '⏪ -' + Math.abs(seconds) + 's'}</span>
  `;
  playerModal.appendChild(ripple);
  setTimeout(() => {
    if (ripple.parentNode) ripple.parentNode.removeChild(ripple);
  }, 600);
}

window.skipTime = function(seconds) {
  const videoElement = document.getElementById('luminaVideo');
  if (!videoElement) return;
  videoElement.currentTime = Math.max(0, videoElement.currentTime + seconds);
  showSeekRipple(seconds);
  showToast((seconds > 0 ? '+' : '') + seconds + 's');
  resetPlayerHideTimer();
};

window.handleSeekbarClick = function(e) {
  const videoElement = document.getElementById('luminaVideo');
  if (!videoElement || !videoElement.duration || isNaN(videoElement.duration)) return;
  const rect = e.currentTarget.getBoundingClientRect();
  const clientX = e.clientX !== undefined ? e.clientX : (e.touches && e.touches[0] ? e.touches[0].clientX : null);
  if (clientX === null) return;
  const pos = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  videoElement.currentTime = pos * videoElement.duration;
  showToast('Seek: ' + formatSeekTime(videoElement.currentTime));
  resetPlayerHideTimer();
};

let orientationModes = ['auto', 'landscape', 'portrait'];
let orientationLabels = ['🔄 Auto-Rotate', '🔄 Landscape', '🔄 Portrait'];
let currentOrientIdx = 0;

window.cycleOrientation = function() {
  currentOrientIdx = (currentOrientIdx + 1) % orientationModes.length;
  const mode = orientationModes[currentOrientIdx];
  if (window.AndroidMedia && window.AndroidMedia.setOrientation) {
    window.AndroidMedia.setOrientation(mode);
  }
  const btnText = document.getElementById('playerRotateText');
  if (btnText) btnText.textContent = orientationLabels[currentOrientIdx];
  showToast(orientationLabels[currentOrientIdx]);
  resetPlayerHideTimer();
};

window.toggleFullScreen = function() {
  const isLandscape = window.innerWidth > window.innerHeight;
  const targetMode = isLandscape ? 'portrait' : 'landscape';
  
  if (window.AndroidMedia && window.AndroidMedia.setOrientation) {
    window.AndroidMedia.setOrientation(targetMode);
  }
  if (window.AndroidMedia && window.AndroidMedia.setFullscreen) {
    window.AndroidMedia.setFullscreen(true);
  }

  const btnText = document.getElementById('playerRotateText');
  if (btnText) {
    btnText.textContent = targetMode === 'landscape' ? '🔄 Landscape' : '🔄 Portrait';
  }

  const curLabel = aspectLabels[currentAspectIdx] || 'Best Fit (16:9)';

  // Show central floating HUD pill with orientation & active aspect ratio
  const hud = document.getElementById('playerSwipeHud');
  const hudIcon = document.getElementById('playerSwipeHudIcon');
  const hudTitle = document.getElementById('playerSwipeHudTitle');
  const hudPct = document.getElementById('playerSwipeHudPct');
  
  if (hud && hudIcon && hudTitle && hudPct) {
    hud.className = 'player-swipe-hud-pill hud-center active';
    hudIcon.textContent = '⛶';
    hudTitle.textContent = targetMode === 'landscape' ? 'Fullscreen (Landscape)' : 'Portrait Mode';
    hudPct.textContent = curLabel;
    clearTimeout(hudHideTimeout);
    hudHideTimeout = setTimeout(() => {
      hud.classList.remove('active');
    }, 1400);
  }

  try {
    const playerModal = document.getElementById('playerModal');
    if (!document.fullscreenElement) {
      if (playerModal && playerModal.requestFullscreen) {
        playerModal.requestFullscreen().catch(() => {});
      }
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().catch(() => {});
      }
    }
  } catch (e) {}
  showToast((targetMode === 'landscape' ? 'Fullscreen (Landscape)' : 'Portrait Mode') + ' • ' + curLabel);
  resetPlayerHideTimer();
};

