// 7. Pop-Up Player (PiP)
window.onEnterPipMode = function() {
  // Instantly hide all full player UI overlays, top/bottom bars, drawers, and HUDs
  const uiOverlay = document.getElementById('playerUiOverlay');
  if (uiOverlay) {
    uiOverlay.classList.remove('active');
    uiOverlay.style.display = 'none';
  }
  const lockOverlay = document.getElementById('playerLockOverlay');
  if (lockOverlay) lockOverlay.style.display = 'none';
  const swipeHud = document.getElementById('playerSwipeHud');
  if (swipeHud) swipeHud.classList.remove('active');
  const ccBox = document.getElementById('playerCcBox');
  if (ccBox) ccBox.style.display = 'none';
  const miniPlayer = document.getElementById('miniPlayer');
  if (miniPlayer) miniPlayer.classList.remove('active');
  const spinner = document.getElementById('playerBufferingSpinner');
  if (spinner) spinner.style.display = 'none';
  const errorOverlay = document.getElementById('playerErrorOverlay');
  if (errorOverlay) errorOverlay.style.display = 'none';
  const brightOverlay = document.getElementById('playerBrightnessOverlay');
  if (brightOverlay) brightOverlay.style.opacity = '0';
  const ambientBackdrop = document.getElementById('playerAmbientBackdrop');
  if (ambientBackdrop) ambientBackdrop.style.display = 'none';

  if (typeof closeVlcMoreMenu === 'function') closeVlcMoreMenu();

  // Keep video element 100% visible and unblanked when paused in PiP
  const video = document.getElementById('luminaVideo');
  if (video) {
    video.style.display = 'block';
    video.style.opacity = '1';
    video.style.zIndex = '9999';
  }

  const playerModal = document.getElementById('playerModal');
  if (playerModal) {
    playerModal.classList.add('active');
    playerModal.style.display = 'flex';
    playerModal.style.background = '#000000';
  }

  // Deterministic GPU compositor frame synchronization for PiP (Task 4)
  try {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (window.AndroidMedia && window.AndroidMedia.onPipSurfaceReady) {
          window.AndroidMedia.onPipSurfaceReady();
        }
      });
    });
  } catch (eRaf) {}
};

window.onExitPipMode = function() {
  const uiOverlay = document.getElementById('playerUiOverlay');
  if (uiOverlay) {
    uiOverlay.style.display = '';
  }
  const ambientBackdrop = document.getElementById('playerAmbientBackdrop');
  if (ambientBackdrop) ambientBackdrop.style.display = '';
  const video = document.getElementById('luminaVideo');
  if (video) {
    video.style.zIndex = '';
  }
  resetPlayerHideTimer();
};

window.triggerVlcPip = function(e) {
  if (e) e.stopPropagation();
  closeVlcMoreMenu();
  if (window.onEnterPipMode) window.onEnterPipMode();

  if (window.AndroidMedia && window.AndroidMedia.enterPipMode) {
    window.AndroidMedia.enterPipMode();
  } else {
    const v = document.getElementById('luminaVideo');
    if (v && document.pictureInPictureEnabled && !document.pictureInPictureElement) {
      v.requestPictureInPicture().catch(() => {
        minimizeToMiniPlayer(null);
      });
    } else {
      minimizeToMiniPlayer(null);
    }
  }
  showToast('Pop-Up Player (PiP)');
};

