// ==========================================================
// ON-DEVICE PROCESSOR DSP & AI SPEECH RECOGNITION ENGINE
// ==========================================================
let currentTrackDelay = 0.0;
let currentSubtitleLanguage = 'hindi';
let currentAudioTrack = 'passthrough';
let speechRecognitionInstance = null;
let webAudioCtx = null;
let webAudioSource = null;
let webAudioVocalFilter = null;
let webAudioPanner = null;

function initWebAudioDSP() {
  try {
    const videoElement = document.getElementById('luminaVideo');
    if (!videoElement) return;
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    
    if (!webAudioCtx) {
      webAudioCtx = new AudioCtx();
    }
    if (webAudioCtx.state === 'suspended') {
      webAudioCtx.resume().catch(() => {});
    }

    // Configure multi-channel downmixing for 4K SDR/HDR Dolby/DTS/Surround audio
    try {
      webAudioCtx.destination.channelCount = 2;
      webAudioCtx.destination.channelCountMode = 'explicit';
      webAudioCtx.destination.channelInterpretation = 'speakers';
    } catch (eC) {}

    // Note: Do NOT call attach WebAudio to HTML media element.
    // In Chromium/Android WebView, routing HTMLMediaElement through WebAudio silences
    // cross-origin media that lack CORS headers, causing complete audio loss.
  } catch (e) {
    console.log('Web Audio DSP initialization note:', e.message);
  }
}

// 1. Dedicated Subtitles & Translations Modal (Bottom Left Toolbar Button)
window.openVlcSubtitlesModal = function(e) {
  if (e) e.stopPropagation();
  closeVlcMoreMenu();
  const modal = document.getElementById('vlcSubtitlesModal');
  if (modal) modal.style.display = 'flex';
};

window.closeVlcSubtitlesModal = function() {
  const modal = document.getElementById('vlcSubtitlesModal');
  if (modal) modal.style.display = 'none';
};

// 2. Dedicated Audio Track & Channels Modal (Under 3-Dots Drawer)
window.openVlcAudioModal = function(e) {
  if (e) e.stopPropagation();
  closeVlcMoreMenu();
  const modal = document.getElementById('vlcAudioModal');
  if (!modal) return;

  const tracksList = document.getElementById('vlcAudioTracksList');
  if (tracksList) {
    let html = '';
    const isHlsMulti = typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.audioTracks && hlsInstance.audioTracks.length > 1;

    if (isHlsMulti) {
      hlsInstance.audioTracks.forEach((track, idx) => {
        const trackName = track.name || track.lang || `Track ${idx + 1}`;
        const isCurrent = hlsInstance.audioTrack === idx;
        html += `
          <div class="vlc-radio-row ${isCurrent ? 'active' : ''}" onclick="setVlcHlsAudioTrack(${idx}, this)">
            <span>📻 ${trackName} (${track.lang ? track.lang.toUpperCase() : 'HLS Audio Track'})</span>
          </div>
        `;
      });
    } else {
      const movie = (typeof currentPlayingChannel !== 'undefined' && currentPlayingChannel && currentPlayingChannel.movieData) || (typeof currentSelectedMovie !== 'undefined' ? currentSelectedMovie : null);
      let streamsMap = (movie && movie.audioStreams) || null;
      if (movie && (movie.mediaType === 'series' || movie.contentType === 'SERIES') && window.currentPlayingEpisodeId && movie.seasons) {
        for (const s of movie.seasons) {
          if (s.episodes) {
            const foundEp = s.episodes.find(e => String(e.id) === String(window.currentPlayingEpisodeId));
            if (foundEp && foundEp.audioStreams) {
              streamsMap = foundEp.audioStreams;
              break;
            }
          }
        }
      }
      if (streamsMap && Object.keys(streamsMap).length > 1) {
        const activeLang = window.selectedMovieAudioLang || (movie && movie.defaultLanguage) || 'Hindi';
        Object.keys(streamsMap).forEach(lang => {
          const isCurrent = (lang === activeLang);
          const icon = lang === 'Hindi' ? '🇮🇳' : (lang === 'English' ? '🌐' : (lang === 'Korean' ? '🎧' : '🎵'));
          html += `
            <div class="vlc-radio-row ${isCurrent ? 'active' : ''}" onclick="switchMovieAudioStream('${lang}', this)">
              <span>${icon} ${lang} Audio Track (Stream Switch)</span>
            </div>
          `;
        });
      } else {
        const primaryLang = (movie && movie.languages && movie.languages[0]) || (movie && movie.defaultLanguage) || 'Master Dialogue';
        html += `
          <div class="vlc-radio-row active" onclick="setVlcAudioTrack('master', this)">
            <span>🎧 ${primaryLang} (Master Audio Track • Studio Dialogue)</span>
          </div>
        `;
      }
    }

    html += `
      <div class="vlc-radio-row ${currentAudioTrack === 'speech_boost' ? 'active' : ''}" onclick="setVlcAudioTrack('speech_boost', this)">
        <span>⚡ Clear Voice Speech AI Boost (Enhanced Vocals)</span>
      </div>
      <div class="vlc-radio-row ${currentAudioTrack === 'passthrough' ? 'active' : ''}" onclick="setVlcAudioTrack('passthrough', this)">
        <span>🔊 Direct Hardware Audio Passthrough</span>
      </div>
    `;

    if (!isHlsMulti) {
      html += `
        <p style="font-size: 11px; color: #64748b; margin-top: 10px; text-align: center; line-height: 1.4;">
          ℹ️ Single Studio Master Audio Track • Multi-track switching is supported for multi-language broadcast streams.
        </p>
      `;
    }

    tracksList.innerHTML = html;
  }

  modal.style.display = 'flex';
};


window.switchMovieAudioStream = function(lang, elem) {
  window.selectedMovieAudioLang = lang;
  localStorage.setItem('t2l_preferred_movie_audio_lang', lang);

  const movie = (typeof currentPlayingChannel !== 'undefined' && currentPlayingChannel && currentPlayingChannel.movieData) || (typeof currentSelectedMovie !== 'undefined' ? currentSelectedMovie : null);
  if (!movie) return;

  let streamsMap = movie.audioStreams || null;
  if ((movie.mediaType === 'series' || movie.contentType === 'SERIES') && window.currentPlayingEpisodeId && movie.seasons) {
    for (const s of movie.seasons) {
      if (s.episodes) {
        const foundEp = s.episodes.find(e => String(e.id) === String(window.currentPlayingEpisodeId));
        if (foundEp && foundEp.audioStreams) {
          streamsMap = foundEp.audioStreams;
          break;
        }
      }
    }
  }

  if (streamsMap && streamsMap[lang]) {
    const newUrl = streamsMap[lang];
    const video = document.getElementById('luminaVideo');
    const savedTime = (video && !isNaN(video.currentTime)) ? video.currentTime : 0;
    const wasPaused = (video && video.paused);

    if (currentPlayingChannel) {
      currentPlayingChannel.url = newUrl;
    }
    if (activePlaybackSession) {
      activePlaybackSession.overrideUrl = newUrl;
    }

    if (video) {
      video.src = newUrl;
      video.currentTime = savedTime;
      if (!wasPaused) {
        video.play().catch(() => {});
      }
    }

    const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
    rows.forEach(r => r.classList.remove('active'));
    if (elem) elem.classList.add('active');

    const subBadge = document.getElementById('vlcAudioSubtitle');
    if (subBadge) subBadge.textContent = lang;

    showToast(`Switched audio track to: ${lang} 🔊`);
  }
};

window.setVlcHlsAudioTrack = function(trackIdx, elem) {
  if (typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.audioTracks && hlsInstance.audioTracks[trackIdx]) {
    hlsInstance.audioTrack = trackIdx;
    const t = hlsInstance.audioTracks[trackIdx];
    const trackName = t.name || t.lang || `Track ${trackIdx + 1}`;
    const subBadge = document.getElementById('vlcAudioSubtitle');
    if (subBadge) subBadge.textContent = trackName;
    const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
    rows.forEach(r => r.classList.remove('active'));
    if (elem) elem.classList.add('active');
    showToast(`Switched audio track to: ${trackName} 🔊`);
  }
};

window.closeVlcAudioModal = function() {
  const modal = document.getElementById('vlcAudioModal');
  if (modal) modal.style.display = 'none';
};

// Aliases for backward compatibility
window.openVlcTracksMenu = window.openVlcSubtitlesModal;
window.closeVlcTracksModal = function() {
  window.closeVlcSubtitlesModal();
  window.closeVlcAudioModal();
};

window.setVlcAudioTrack = function(trackId, elem) {
  currentAudioTrack = trackId;
  const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
  rows.forEach(r => r.classList.remove('active'));
  if (elem) elem.classList.add('active');

  const subBadge = document.getElementById('vlcAudioSubtitle');
  const shortNames = {
    'hindi': 'Hindi',
    'telugu': 'Telugu',
    'tamil': 'Tamil',
    'kannada': 'Kannada',
    'malayalam': 'Malayalam',
    'marathi': 'Marathi',
    'english': 'English',
    'universal audio': 'Universal',
    'dual_left': 'Left (Hindi)',
    'dual_right': 'Right (Eng)',
    'speech_boost': 'Voice AI',
    'passthrough': 'Direct 4K'
  };
  localStorage.setItem('t2l_preferred_movie_audio_lang', shortNames[trackId] || trackId);
  if (subBadge) subBadge.textContent = shortNames[trackId] || 'Hindi';

  const videoElement = document.getElementById('luminaVideo');
  if (videoElement) {
    videoElement.muted = false; // Ensure direct unmuted hardware sound
    if (videoElement.audioTracks && videoElement.audioTracks.length > 0) {
      let matchedIdx = -1;
      const targetQuery = (trackId === 'hindi' ? 'hi' : (trackId === 'english' ? 'en' : trackId)).toLowerCase();
      for (let i = 0; i < videoElement.audioTracks.length; i++) {
        const tr = videoElement.audioTracks[i];
        const tLang = (tr.language || '').toLowerCase();
        const tLabel = (tr.label || '').toLowerCase();
        if (tLang === targetQuery || tLang.startsWith(targetQuery) || tLabel.includes(targetQuery) || (targetQuery === 'hi' && (tLang.includes('hin') || tLabel.includes('hindi')))) {
          matchedIdx = i;
          break;
        }
      }
      if (matchedIdx >= 0) {
        for (let i = 0; i < videoElement.audioTracks.length; i++) {
          videoElement.audioTracks[i].enabled = (i === matchedIdx);
        }
      } else {
        for (let i = 0; i < videoElement.audioTracks.length; i++) {
          videoElement.audioTracks[i].enabled = (trackId === 'english' || trackId === 'dual_right' ? i === 1 : i === 0);
        }
      }
    }
  }

  const CANONICAL_LANG_MAP = {
    'hindi': 'hi', 'hin': 'hi', 'हिन्दी': 'hi',
    'english': 'en', 'eng': 'en',
    'japanese': 'ja', 'jpn': 'ja',
    'korean': 'ko', 'kor': 'ko',
    'telugu': 'te', 'tel': 'te',
    'tamil': 'ta', 'tam': 'ta',
    'kannada': 'kn', 'kan': 'kn',
    'malayalam': 'ml', 'mal': 'ml',
    'marathi': 'mr', 'mar': 'mr',
    'bengali': 'bn', 'ben': 'bn',
    'spanish': 'es', 'spa': 'es'
  };

  // Real HLS audio track switching via Hls.js with canonical normalization
  if (typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.audioTracks && hlsInstance.audioTracks.length > 0) {
    const rawTarget = (shortNames[trackId] || trackId).toLowerCase();
    const targetNorm = CANONICAL_LANG_MAP[rawTarget] || rawTarget;
    const trackIndex = hlsInstance.audioTracks.findIndex(t => {
      const tLang = (t.lang || '').toLowerCase();
      const tNorm = CANONICAL_LANG_MAP[tLang] || tLang;
      const tName = (t.name || '').toLowerCase();
      return tNorm === targetNorm || tLang.includes(targetNorm) || tName.includes(targetNorm) || tName.includes(rawTarget);
    });
    if (trackIndex >= 0) {
      hlsInstance.audioTrack = trackIndex;
      console.log('Switched Hls.js audioTrack to:', trackIndex, hlsInstance.audioTracks[trackIndex]);
    }
  }

  // Apply real-time on-device processor DSP filtering
  if (webAudioCtx && webAudioVocalFilter) {
    if (trackId === 'speech_boost') {
      webAudioVocalFilter.gain.value = 8.0;
    } else if (trackId === 'hindi') {
      webAudioVocalFilter.gain.value = 4.5;
    } else if (trackId === 'english') {
      webAudioVocalFilter.gain.value = 3.5;
    } else {
      webAudioVocalFilter.gain.value = 0;
    }

    if (webAudioPanner) {
      if (trackId === 'dual_left') {
        webAudioPanner.pan.value = -1.0;
      } else if (trackId === 'dual_right') {
        webAudioPanner.pan.value = 1.0;
      } else {
        webAudioPanner.pan.value = 0;
      }
    }
  }

  const trackNames = {
    'hindi': 'Hindi (Dialogue Enhanced)',
    'english': 'English (Broadcast Stream)',
    'dual_left': 'Dual-Track Left Channel (Hindi)',
    'dual_right': 'Dual-Track Right Channel (English)',
    'speech_boost': 'Clear Voice Speech AI Boost',
    'passthrough': 'Dolby / Direct Passthrough (All 4K Audios)'
  };

  showToast('Audio: ' + (trackNames[trackId] || 'Track Active'));
  closeVlcAudioModal();
};

