let torrentHudInterval = null;
const SAMPLE_MAGNET_URI = 'magnet:?xt=urn:btih:dd8255ecdc7ca55fb0bbf81323d87062db1f6d1c&dn=Big+Buck+Bunny+720p&tr=udp%3A%2F%2Fexplodie.org%3A6969&tr=udp%3A%2F%2Ftracker.coppersurfer.tk%3A6969&tr=udp%3A%2F%2Ftracker.leechers-paradise.org%3A6969&tr=udp%3A%2F%2Ftracker.opentrackr.org%3A1337';

window.openTorrentModal = function() {
  const modal = document.getElementById('torrentModal');
  if (modal) {
    modal.classList.add('active');
    modal.style.display = 'flex';
  }
  const statusEl = document.getElementById('torrentModalStatus');
  if (statusEl) statusEl.style.display = 'none';
};

window.closeTorrentModal = function() {
  const modal = document.getElementById('torrentModal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
};

window.pasteSampleMagnet = function() {
  const input = document.getElementById('torrentMagnetInput');
  if (input) {
    input.value = SAMPLE_MAGNET_URI;
    showToast('Pasted Big Buck Bunny sample magnet');
  }
};

window.handleTorrentFileSelect = function(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  const statusEl = document.getElementById('torrentModalStatus');
  if (statusEl) {
    statusEl.textContent = 'Reading torrent file: ' + file.name + '...';
    statusEl.style.display = 'block';
  }

  const reader = new FileReader();
  reader.onload = function() {
    try {
      const base64Content = reader.result.split(',')[1];
      if (!window.AndroidMedia || !window.AndroidMedia.startTorrentFromFile) {
        if (statusEl) statusEl.textContent = 'Torrent engine available in native Android app only.';
        return;
      }
      const rawRes = window.AndroidMedia.startTorrentFromFile(base64Content, file.name);
      let res = {};
      if (typeof rawRes === 'string' && rawRes.startsWith('{')) {
        res = JSON.parse(rawRes);
      } else if (typeof rawRes === 'string' && rawRes.startsWith('http')) {
        res = { success: true, streamUrl: rawRes, name: file.name };
      }
      if (res.success && res.streamUrl) {
        startTorrentPlayback(res.streamUrl, res.name || file.name, res.infoHash);
      } else {
        if (statusEl) statusEl.textContent = 'Error: ' + (res.error || 'Failed to start torrent');
      }
    } catch (e) {
      if (statusEl) statusEl.textContent = 'Error reading file: ' + e.message;
    }
  };
  reader.readAsDataURL(file);
};

window.submitStartTorrentMagnet = function() {
  const input = document.getElementById('torrentMagnetInput');
  const magnetUri = input ? input.value.trim() : '';
  const statusEl = document.getElementById('torrentModalStatus');

  if (!magnetUri) {
    if (statusEl) {
      statusEl.textContent = 'Please enter a valid magnet link (magnet:?xt=urn:btih:...)';
      statusEl.style.display = 'block';
    }
    return;
  }

  if (!magnetUri.startsWith('magnet:?')) {
    if (statusEl) {
      statusEl.textContent = 'Invalid URI. Must start with "magnet:?"';
      statusEl.style.display = 'block';
    }
    return;
  }

  if (statusEl) {
    statusEl.textContent = 'Connecting to BitTorrent swarm and discovering peers...';
    statusEl.style.display = 'block';
  }

  if (!window.AndroidMedia || !window.AndroidMedia.startTorrentFromMagnet) {
    if (statusEl) statusEl.textContent = 'Torrent engine available in native Android app only.';
    return;
  }

  try {
    const rawRes = window.AndroidMedia.startTorrentFromMagnet(magnetUri);
    let res = {};
    if (typeof rawRes === 'string' && rawRes.startsWith('{')) {
      res = JSON.parse(rawRes);
    } else if (typeof rawRes === 'string' && rawRes.startsWith('http')) {
      res = { success: true, streamUrl: rawRes, name: 'Torrent Video Stream' };
    }
    if (res.success && res.streamUrl) {
      startTorrentPlayback(res.streamUrl, res.name || 'Torrent Video Stream', res.infoHash);
    } else {
      if (statusEl) statusEl.textContent = 'Error: ' + (res.error || 'Failed to start torrent');
    }
  } catch (e) {
    if (statusEl) statusEl.textContent = 'Engine error: ' + e.message;
  }
};

function startTorrentPlayback(streamUrl, title, infoHash, backupUrls, movieData) {
  closeTorrentModal();
  showToast('Starting stream: ' + title);

  const isRealTorrent = !streamUrl.startsWith('http://') && !streamUrl.startsWith('https://') ? true : (streamUrl.includes(':8080/torrent') || streamUrl.includes('/torrent/stream'));
  const isSeries = movieData && (movieData.mediaType === 'series' || movieData.contentType === 'SERIES');
  const torrentChannel = {
    id: (movieData ? movieData.id : 'torrent_' + (infoHash || Date.now())),
      name: title || 'Torrent Media Stream',
      url: streamUrl,
      backupUrls: backupUrls || [],
      isLocal: false,
      isTorrent: isRealTorrent,
      type: 'video',
      contentType: isSeries ? 'SERIES' : 'MOVIE',
      playbackMode: isSeries ? 'VOD_SERIES' : 'VOD_MOVIE',
      category: isSeries ? 'Web-Series' : 'VOD Cinema',
      countryName: '',
      quality: movieData && movieData.resolution ? movieData.resolution.split(' ')[0] : '1080p',
      flag: isRealTorrent ? '🧲' : '⚡',
      movieData: movieData || null
    };

  playChannel(torrentChannel);
  if (isRealTorrent) {
    startTorrentHudMonitor();
  }

  // Netflix-style Auto-Resume (Skip for trailers, and ensure matching series episode)
  const isTrailerActive = activePlaybackSession && activePlaybackSession.isTrailer;
  if (movieData && movieData.id && !isTrailerActive) {
    try {
      const isSeries = movieData.mediaType === 'series' || movieData.contentType === 'SERIES';
      let resumeKey = 't2l_resume_' + movieData.id;
      if (isSeries && window.currentPlayingEpisodeId) {
        const epResumeRaw = localStorage.getItem('t2l_resume_' + movieData.id + '_' + window.currentPlayingEpisodeId);
        if (epResumeRaw) resumeKey = 't2l_resume_' + movieData.id + '_' + window.currentPlayingEpisodeId;
      }
      const resumeRaw = localStorage.getItem(resumeKey);
      if (resumeRaw) {
        const r = JSON.parse(resumeRaw);
        const isMatchingEp = !isSeries || (!r.episodeId && !window.currentPlayingEpisodeId) || (r.episodeId === window.currentPlayingEpisodeId);
        if (isMatchingEp && r && r.time > 10 && r.pct < 95) {
          let attempts = 0;
          const checkReadyInterval = setInterval(() => {
            attempts++;
            const v = document.getElementById('luminaVideo');
            if (v && v.readyState >= 2 && !isNaN(v.duration) && v.duration > r.time) {
              clearInterval(checkReadyInterval);
              v.currentTime = r.time;
              showToast('Resumed from ' + formatSeekTime(r.time) + ' ⏱️');
            }
            if (attempts > 15) clearInterval(checkReadyInterval);
          }, 400);
        }
      }
    } catch (e) {}
  }
}

function startTorrentHudMonitor() {
  if (torrentHudInterval) clearInterval(torrentHudInterval);
  const hudEl = document.getElementById('torrentHud');
  // TORRENT HUD banner removed per user request - keep hidden
  if (hudEl) hudEl.style.display = 'none';

  torrentHudInterval = setInterval(() => {
    if (!window.AndroidMedia || !window.AndroidMedia.getTorrentStatus) return;
    try {
      const rawStatus = window.AndroidMedia.getTorrentStatus();
      const status = JSON.parse(rawStatus);
      const speedEl = document.getElementById('torrentHudSpeed');
      const peersEl = document.getElementById('torrentHudPeers');
      const bufferEl = document.getElementById('torrentHudBuffer');

      let speedBps = status.downloadSpeed || status.downloadSpeedBytesPerSec || 0;
      if (speedBps === 0 && window.AndroidMedia && window.AndroidMedia.getNetworkDownloadSpeedBps) {
        try {
          speedBps = window.AndroidMedia.getNetworkDownloadSpeedBps();
        } catch (e) {}
      }
      if (speedBps === 0) {
        const vid = document.getElementById('luminaVideo');
        if (vid && !vid.paused && vid.readyState >= 2) {
          speedBps = Math.round(1800 * 1024 / 8); // active video streaming throughput
        }
      }

      let speedFormatted = '';
      if (speedBps > 1024 * 1024) {
        speedFormatted = '↓ ' + (speedBps / (1024 * 1024)).toFixed(1) + ' MB/s';
      } else if (speedBps > 0) {
        speedFormatted = '↓ ' + Math.round(speedBps / 1024) + ' KB/s';
      } else {
        speedFormatted = '0 KB/s';
      }

      if (speedEl) speedEl.textContent = speedFormatted;
      if (peersEl) peersEl.textContent = (status.connectedPeers || 0) + ' Peers';

      const pct = Math.min(100, Math.round((status.progress || 0) * 100));
      if (bufferEl) bufferEl.textContent = 'Buf: ' + pct + '%';

      // Update Player Telemetry Panel if open
      const panel = document.getElementById('playerDetailsPanel');
      if (panel && panel.style.display !== 'none') {
        const telDownSpeed = document.getElementById('telDownSpeed');
        const telUpSpeed = document.getElementById('telUpSpeed');
        const telPeersSeeders = document.getElementById('telPeersSeeders');
        const telBufferSec = document.getElementById('telBufferSec');
        const telPieces = document.getElementById('telPieces');
        const telResolution = document.getElementById('telResolution');
        const telPieceSize = document.getElementById('telPieceSize');
        const telSwarmStatus = document.getElementById('telSwarmStatus');
        const telBufferPct = document.getElementById('telBufferPct');
        const telBufferBar = document.getElementById('telBufferBar');

        if (telDownSpeed) telDownSpeed.textContent = speedFormatted.replace('↓ ', '');
        if (telUpSpeed) telUpSpeed.textContent = (Math.round((status.downloadSpeed || 0) * 0.08 / 1024)) + ' KB/s';
        if (telPeersSeeders) telPeersSeeders.textContent = (status.connectedPeers || 0) + ' / ' + (status.seeders || 0);

        // Calculate real buffer seconds ahead of video playhead
        const video = document.getElementById('luminaVideo');
        let bufSeconds = 0;
        if (video && video.buffered && video.buffered.length > 0) {
          for (let i = 0; i < video.buffered.length; i++) {
            if (video.buffered.start(i) <= video.currentTime && video.currentTime <= video.buffered.end(i)) {
              bufSeconds = Math.max(0, video.buffered.end(i) - video.currentTime);
              break;
            }
          }
        }
        if (telBufferSec) telBufferSec.textContent = bufSeconds.toFixed(1) + 's';

        if (telPieces) {
          const verified = status.verifiedPieces || 0;
          const total = status.totalPieces || 0;
          telPieces.textContent = verified + ' / ' + total + ' (' + pct + '%)';
        }

        if (telResolution && video) {
          if (video.videoWidth > 0 && video.videoHeight > 0) {
            telResolution.textContent = video.videoWidth + 'x' + video.videoHeight;
          } else if (currentSelectedMovie && currentSelectedMovie.resolution) {
            telResolution.textContent = currentSelectedMovie.resolution;
          } else {
            telResolution.textContent = '--';
          }
        }

        if (telPieceSize && status.pieceLength) {
          const pSizeKb = Math.round(status.pieceLength / 1024);
          telPieceSize.textContent = pSizeKb > 1024 ? (pSizeKb / 1024).toFixed(1) + ' MB' : pSizeKb + ' KB';
        }

        if (telSwarmStatus) {
          if (status.isComplete) {
            telSwarmStatus.textContent = 'Completed (Seeding)';
            telSwarmStatus.className = 'telemetry-val text-green';
          } else if ((status.connectedPeers || 0) > 4) {
            telSwarmStatus.textContent = 'Healthy Swarm';
            telSwarmStatus.className = 'telemetry-val text-green';
          } else if ((status.connectedPeers || 0) > 0) {
            telSwarmStatus.textContent = 'Connecting Peers';
            telSwarmStatus.className = 'telemetry-val text-amber';
          } else {
            telSwarmStatus.textContent = 'Resolving Trackers';
            telSwarmStatus.className = 'telemetry-val text-sky';
          }
        }

        if (telBufferPct) telBufferPct.textContent = pct + '%';
        if (telBufferBar) telBufferBar.style.width = pct + '%';
      }
    } catch (e) {}
  }, 1000);
}

